/**
 * Normalizes French accent characters to base ASCII for resilient fallback lookup
 */
export function stripAccents(str: string): string {
  return str
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

/**
 * Looks up any French token in the comprehensive Portuguese lexicon.
 * Tries exact normalized match first, then stripped accent match, then singular/masculine fallback.
 */
export function lookupFrenchLexicon(rawWord: string): LexiconEntry | null {
  if (!rawWord) return null;
  const clean = rawWord.toLowerCase().replace(/^[’‘´`']+|[’‘´`'.!?,;:()«»"—]+$/g, '').trim();
  if (!clean) return null;

  // 1. Exact match (preserves explicit accents like à, où, là)
  if (FRENCH_PORTUGUESE_LEXICON[clean]) {
    return FRENCH_PORTUGUESE_LEXICON[clean];
  }

  // 2. Accent-insensitive match
  const stripped = stripAccents(clean);
  if (FRENCH_PORTUGUESE_LEXICON[stripped]) {
    return FRENCH_PORTUGUESE_LEXICON[stripped];
  }

  // 3. Simple plural fallback (-s or -x)
  if (clean.endsWith('s') && clean.length > 2) {
    const singular = clean.slice(0, -1);
    const found = FRENCH_PORTUGUESE_LEXICON[singular] || FRENCH_PORTUGUESE_LEXICON[stripAccents(singular)];
    if (found) {
      return {
        ...found,
        translationPt: `${found.translationPt} (plural)`,
      };
    }
  }

  if (clean.endsWith('x') && clean.length > 3) {
    const singularAu = clean.endsWith('aux') ? clean.slice(0, -2) + 'l' : clean.slice(0, -1);
    const found = FRENCH_PORTUGUESE_LEXICON[singularAu] || FRENCH_PORTUGUESE_LEXICON[stripAccents(singularAu)];
    if (found) {
      return {
        ...found,
        translationPt: `${found.translationPt} (plural)`,
      };
    }
  }

  // 4. Feminine adjective fallback (-e or -ée)
  if (clean.endsWith('e') && clean.length > 2) {
    const masculine = clean.slice(0, -1);
    const found = FRENCH_PORTUGUESE_LEXICON[masculine] || FRENCH_PORTUGUESE_LEXICON[stripAccents(masculine)];
    if (found) {
      return {
        ...found,
        translationPt: `${found.translationPt} (fem.)`,
      };
    }
  }

  return null;
}
